import numpy as np
from scipy import stats
from sklearn.metrics import roc_auc_score
from sklearn.linear_model import LogisticRegression
from sklearn.preprocessing import StandardScaler

MAX_DRIVERS = 3

def design(feats):
    # Find features with significant association (p < 0.05)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('copy_number', 'expression', 'clinical'):
            t_stat = feats.x[:, i].T @ feats.y
            p_val = 2 * (1 - stats.t.cdf(abs(t_stat), feats.n - 1))
            if p_val < 0.05:
                sig_features.append((fid, t_stat, p_val))

    # Sort by effect size (absolute t-statistic)
    sig_features.sort(key=lambda x: abs(x[1]), reverse=True)

    # Check for product terms among top features
    top_features = [f[0] for f in sig_features[:10]]

    # Remove near-duplicates (correlated pairs with |r| >= 0.6)
    correlated_pairs = set()
    for a, b in [('AEMF13', 'UUNV6'), ('QURK8', 'AEMF13'), ('QURK8', 'UUNV6'),
                 ('QURK8', 'WAOM6L'), ('WAOM6L', 'AEMF13'), ('NSR15', 'QURK8'),
                 ('WAOM6L', 'UUNV6'), ('IRCP17', 'UUNV6'), ('LVH11', 'DOVX18P'),
                 ('VLDP13', 'UUNV6'), ('MWS4', 'HEDJ5L'), ('WWL5P', 'AEMF13'),
                 ('DTL11', 'WAOM6L'), ('YZH11A', 'UUNV6'), ('IRCP17', 'QURK8'),
                 ('QURK8', 'LUF3'), ('IRCP17', 'AEMF13'), ('LUF3', 'UUNV6'),
                 ('IFP11', 'NPB8'), ('VLDP13', 'AEMF13')]:
        if a in top_features and b in top_features:
            correlated_pairs.add((min(a,b), max(a,b)))

    # Filter out correlated features
    unique_features = []
    for fid in top_features:
        is_correlated = any(fid in pair for pair in correlated_pairs)
        if not is_correlated or fid not in [p[0] for p in correlated_pairs] + [p[1] for p in correlated_pairs]:
            unique_features.append(fid)

    # Try product terms
    best_auc = 0
    best_design = None

    # Test up to 3 driver features
    for k in range(min(len(unique_features), MAX_DRIVERS)):
        candidates = unique_features[:k+1]
        if len(candidates) == 0:
            continue

        # Try all combinations of product terms
        product_terms = []
        for i in range(len(candidates)):
            for j in range(i, len(candidates)):
                if i == j:
                    # Add squared term
                    product_terms.append((candidates[i], candidates[j]))
                else:
                    # Add product term
                    product_terms.append((candidates[i], candidates[j]))

        # Score each combination using cross-validation
        for a, b in product_terms:
            if a == b:
                # Squared term
                cols = [feats.column(a)]
                X = feats.x[:, cols]**2
            else:
                # Product term
                cols = [feats.column(a), feats.column(b)]
                X = feats.x[:, cols[0]] * feats.x[:, cols[1]]

            # Simple CV-like scoring
            if len(np.unique(X)) > 1:
                try:
                    auc = roc_auc_score(feats.y, X)
                    if auc > best_auc:
                        best_auc = auc
                        best_design = Design(
                            drivers=(a,) if a == b else (a, b),
                            columns=(a, b) if a != b else (a,),
                            products=((a, b),) if a != b else (),
                            loadings={a: 1.0} if a == b else {a: 1.0, b: 1.0}
                        )
                except:
                    pass

    # If we found good product terms, return them
    if best_design is not None:
        return best_design

    # Otherwise, return just the strongest single feature
    if sig_features:
        strongest_fid = sig_features[0][0]
        return Design(
            drivers=(strongest_fid,),
            columns=(strongest_fid,),
            products=(),
            loadings={strongest_fid: 1.0}
        )

    # No mechanism found
    return Design(drivers=(), columns=(), products=(), loadings={})

